"""Deterministic permissions review and risk explanation. Generated by code from the validated spec, never by a model."""
from __future__ import annotations

from aether.studio import capabilities
from aether.studio.assist.ceiling import Ceiling
from aether.studio.schema import canonical_json, sha256_hex

LABEL = 'AI-PROPOSED, not yet reviewed'
LEVELS = ('low', 'medium', 'high')
MEANING = {
    'demo.run': 'Runs simulated DEMO steps only; nothing real happens.',
    'workspace.read': 'Can read files in the workspace.',
    'workspace.write': 'Can create and change files in the workspace.',
    'artifact.write': 'Can save output files (artifacts) from a run.',
    'net.egress.allowlist': 'Can contact the listed network hosts and nothing else.',
    'provider.local': 'Can call your local model endpoint.',
    'adapter.submit': 'Can hand work to the enrolled adapter you picked.',
    'adapter.observe': 'Can watch the enrolled adapter and record what it reports.',
    'adapter.cancel': 'Can ask the enrolled adapter to cancel work.',
}


def _max(a, b):
    return a if LEVELS.index(a) >= LEVELS.index(b) else b


def risk(spec: dict) -> dict:
    """Level = highest single reason. Reasons are derived only from the spec fields below, in a fixed order."""
    reasons = []

    def add(level, text):
        reasons.append({'level': level, 'reason': text})
    for cap in sorted(spec['capabilities']):
        registered = capabilities.REGISTRY[cap]
        add(registered.risk, f'capability {cap}: {registered.description}'
            + ('; every use needs a human approval' if registered.requires_approval else ''))
    if spec['network_allowlist']:
        add('high', 'outbound network to: ' + ', '.join(sorted(spec['network_allowlist'])))
    ws = spec['workspace']
    if ws['kind'] == 'mounted':
        add('medium', f'mounted workspace {ws["mount"]} ({ws["access"]})')
    if ws['access'] == 'rw':
        add('medium', 'workspace is writable')
    if spec['executor']['kind'] == 'adapter':
        add('medium', f'runs through enrolled adapter {spec["executor"]["ref"]}')
    if spec['limits']['wall_seconds'] > 600:
        add('medium', f'wall time {spec["limits"]["wall_seconds"]}s is longer than ten minutes')
    if spec['limits']['max_workers'] > 1 or any(s.get('max_workers', 1) > 1 for s in spec['stages']):
        add('low', 'stages may run in parallel')
    if not reasons:
        add('low', 'no capabilities requested')
    level = 'low'
    for item in reasons:
        level = _max(level, item['level'])
    return {'level': level, 'reasons': reasons}


def permissions(spec: dict) -> dict:
    ws, limits = spec['workspace'], spec['limits']
    return {
        'capabilities': [{'id': c, 'risk': capabilities.REGISTRY[c].risk, 'meaning': MEANING[c],
                          'requires_approval': capabilities.REGISTRY[c].requires_approval} for c in sorted(spec['capabilities'])],
        'network': ([{'host': h, 'meaning': f'May connect to {h}.'} for h in sorted(spec['network_allowlist'])]
                    or 'none: no outbound network access'),
        'workspace': ('scratch (empty, discarded)' if ws['kind'] == 'scratch' else f'mounted workspace {ws["mount"]}')
        + (', read-only' if ws['access'] == 'ro' else ', read and write'),
        'executor': ('DEMO executor (simulated)' if spec['executor']['kind'] == 'mock'
                     else f'enrolled adapter {spec["executor"]["ref"]}'),
        'limits': [
            {'name': 'wall_seconds', 'value': limits['wall_seconds'], 'meaning': f'The whole run stops after {limits["wall_seconds"]} seconds.'},
            {'name': 'max_workers', 'value': limits['max_workers'], 'meaning': f'At most {limits["max_workers"]} stage(s) run at once.'},
            {'name': 'tokens', 'value': limits['tokens'], 'meaning': 'No model tokens may be spent.' if limits['tokens'] == 0 else f'Up to {limits["tokens"]} model tokens.'},
            {'name': 'cost_usd_cents', 'value': limits['cost_usd_cents'], 'meaning': 'No money may be spent.' if limits['cost_usd_cents'] == 0 else f'Up to {limits["cost_usd_cents"]} US cents.'}],
        'approvals': [{'stage': a['stage'], 'capability': a['capability']} for a in spec['approvals']],
    }


def build(spec: dict, ceiling: Ceiling, changes: list[dict]) -> dict:
    """The review shown to the human. ``changes`` is what the clamp removed/lowered/replaced/added."""
    used = {c for c in spec['capabilities']}
    review = {'label': LABEL, 'risk': risk(spec), 'permissions': permissions(spec),
              'diff_vs_ceiling': {'ceiling': ceiling.as_dict(), 'within_ceiling': True,
                                  'requested_but_removed': changes,
                                  'unused_headroom': sorted(set(ceiling.capabilities) - used)}}
    review['review_sha256'] = sha256_hex(canonical_json(review))
    return review
